        "node": {"table": "channels", "filters": [{"key": "f_chan", "field": "channel_name", "op": "eq", "value": "incidents"}], "edges": []}},
       {"key": "e_auth", "join": {"parent": "user_id", "child": "user_id", "op": "eq"},
        "node": {"table": "users", "filters": [{"key": "f_auth", "field": "real_name", "op": "eq", "value": "Diego Alvarez"}], "edges": []}}
      ]
     }
    },
    "explanation": "Diego Alvarez posted this himself about the payment gateway; it has no parent, so it is a thread root, not a reply in Leo's thread."
   },
   {
    "witness": "@diego_reply_other",
    "fact": "H:messages.parent_id",
    "family": "F2",
    "substitute": "a reply in a different thread",
    "mutation": {
     "type": "REPLACE",
