     "query": {
      "table": "messages",
      "key": ["message_id"],
      "filters": [],
      "edges": [
       {"key": "e_chan", "join": {"parent": "channel_id", "child": "channel_id", "op": "eq"},
        "node": {"table": "channels", "filters": [{"key": "f_chan", "field": "channel_name", "op": "eq", "value": "incidents"}], "edges": []}},
       {"key": "e_auth", "join": {"parent": "user_id", "child": "user_id", "op": "eq"},
        "node": {"table": "users", "filters": [{"key": "f_auth", "field": "real_name", "op": "eq", "value": "Diego Alvarez"}], "edges": []}},
       {"key": "e_thread", "join": {"parent": "parent_id", "child": "message_id", "op": "eq"},
        "node": {"table": "messages", "filters": [{"key": "f_root_text2", "field": "message_text", "op": "contains_ci", "value": "database migration"}],
         "edges": [
          {"key": "e_root_auth2", "join": {"parent": "user_id", "child": "user_id", "op": "eq"},
           "node": {"table": "users", "filters": [{"key": "f_root_auth2", "field": "real_name", "op": "eq", "value": "Omar Haddad"}], "edges": []}}
         ]}}
      ]
     }
    },
    "explanation": "Diego's reply here answers Omar's database-migration thread, not Leo's payment-gateway outage thread."
   }
  ],
  "effect": {"table": "message_reactions", "changes": ["insert"], "key": ["message_id", "user_id", "reaction_type"], "field": "message_id"},
  "written": ["message_reactions.reaction_type"]
 },
